using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tool that fetches data from an external API using an injected HttpClient.
/// </summary>
internal class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool]
    [Description("Fetches JSON data from the specified URL and returns it as a string.")]
    public async Task<string> FetchJson(
        [Description("The absolute URL to fetch JSON from")] string url)
    {
        logger.LogInformation("Fetching JSON from {Url}", url);

        using var response = await httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();

        // Re-serialize to pretty-printed form for readability.
        using var doc = JsonDocument.Parse(json);
        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

/// <summary>
/// MCP prompt templates for summarization tasks.
/// </summary>
internal class SummarizationPrompts
{
    [McpServerPrompt]
    [Description("Generates a prompt that asks the model to summarize the given text.")]
    public static ChatMessage Summarize(
        [Description("The text to summarize")] string text,
        [Description("Maximum number of sentences in the summary (default: 3)")] int maxSentences = 3)
    {
        return new ChatMessage(
            ChatRole.User,
            $"""
             Please summarize the following text in at most {maxSentences} sentence(s).
             Be concise and capture the key points.

             Text:
             {text}
             """);
    }
}

/// <summary>Simple role / content pair returned by prompt templates.</summary>
internal record ChatMessage(ChatRole Role, string Content);

/// <summary>Chat message role.</summary>
internal enum ChatRole { User, Assistant, System }

