using System.ComponentModel;
using ModelContextProtocol.Server;

/// <summary>
/// MCP prompt templates for summarization tasks.
/// </summary>
internal class SummarizationPrompts
{
    [McpServerPrompt]
    [Description("Generates a prompt that asks the model to summarize the given text.")]
    public static string Summarize(
        [Description("The text to summarize")] string text,
        [Description("Maximum number of sentences in the summary (default: 3)")] int maxSentences = 3)
    {
        return $"""
            Please summarize the following text in at most {maxSentences} sentence(s).
            Be concise and capture the key points.

            Text:
            {text}
            """;
    }
}

